package com.autoops.workflow.service;import com.autoops.credential.repository.CredentialRepository;import com.autoops.credential.service.CredentialCryptoService;import com.autoops.execution.executor.*;import com.autoops.infrastructure.remote.RemoteClient;import com.autoops.machine.repository.MachineRepository;import com.autoops.workflow.entity.*;import com.autoops.workflow.repository.WorkflowStepRepository;import org.springframework.stereotype.Service;import java.util.*;@Service public class WorkflowExecutionService{private final WorkflowStepRepository steps;private final MachineRepository machines;private final CredentialRepository credentials;private final CredentialCryptoService crypto;private final List<StepExecutor<?>> executors;public WorkflowExecutionService(WorkflowStepRepository s,MachineRepository m,CredentialRepository c,CredentialCryptoService x,List<StepExecutor<?>> e){steps=s;machines=m;credentials=c;crypto=x;executors=e;}public Result run(Long workflowId,Long machineId,Long credentialId){var all=steps.findByWorkflowIdOrderByPosition(workflowId);if(all.isEmpty())throw new IllegalArgumentException("Workflow has no steps");Map<Long,WorkflowStep>byId=new HashMap<>();all.forEach(s->byId.put(s.getId(),s));WorkflowStep current=all.get(0);var m=machines.findById(machineId).orElseThrow();var c=credentials.findById(credentialId).orElseThrow();var ctx=new StepExecutor.ExecutionContext(m.getHostname(),m.getSshPort(),c.getUsername(),crypto.decrypt(c.getEncryptedPassword(),c.getEncryptionIv()));int guard=0;while(current!=null&&guard++<=all.size()){var r=execute(current,ctx);Long next=r.success()?current.getSuccessNextStepId():current.getFailureNextStepId();if(!r.success()&&next==null)return new Result(false,current.getId(),r.stderr());current=next==null?null:byId.get(next);}if(guard>all.size())throw new IllegalStateException("Workflow cycle detected at runtime");return new Result(true,null,null);}private StepExecutor.StepResult execute(WorkflowStep s,StepExecutor.ExecutionContext c){for(StepExecutor<?> e:executors)if(e.supports().isInstance(s))return call(e,s,c);throw new IllegalArgumentException("Unsupported workflow step");}@SuppressWarnings({"rawtypes","unchecked"})private StepExecutor.StepResult call(StepExecutor e,WorkflowStep s,StepExecutor.ExecutionContext c){return e.execute(s,c);}public record Result(boolean success,Long failedStepId,String error){}}
